lib='''"""Reusable grid functions for ARC tasks."""
from collections import deque

def background(grid):
    """The most frequent color in the grid."""
    return max({v for row in grid for v in row}, key=lambda c: sum(row.count(c) for row in grid))

def border_reachable_bg(grid, bg=None):
    """Boolean grid: background cells 8-connected to the grid border."""
    if bg is None: bg = background(grid)
    h, w = len(grid), len(grid[0])
    R = [[False]*w for _ in range(h)]; q = deque()
    for i in range(h):
        for j in (0, w-1):
            if grid[i][j] == bg and not R[i][j]: R[i][j] = True; q.append((i, j))
    for j in range(w):
        for i in (0, h-1):
            if grid[i][j] == bg and not R[i][j]: R[i][j] = True; q.append((i, j))
    while q:
        i, j = q.popleft()
        for a in (-1, 0, 1):
            for b in (-1, 0, 1):
                ni, nj = i+a, j+b
                if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == bg and not R[ni][nj]:
                    R[ni][nj] = True; q.append((ni, nj))
    return R

def fill_enclosed(grid, fill=4, bg=None):
    """Cells with no 8-connected path to the border through background become fill color."""
    if bg is None: bg = background(grid)
    h, w = len(grid), len(grid[0])
    R = border_reachable_bg(grid, bg)
    return [[fill if not R[i][j] and not any(R[i+a][j+b] for a in (-1, 0, 1) for b in (-1, 0, 1)
             if 0 <= i+a < h and 0 <= j+b < w) else grid[i][j] for j in range(w)] for i in range(h)]
'''
